/*! Lightweight jQuery Validate Stub for Production Management v2 */
(function($){
	'use strict';

	if (!$.fn) { return; }

	function Validator(options, form) {
		this.settings = $.extend({
			errorClass: 'error',
			validClass: 'valid',
			submitHandler: null
		}, options || {});
		this.currentForm = form || null;
	}

	Validator.prototype = {
		form: function() { return true; },
		element: function() { return true; },
		resetForm: function() {},
		reset: function() {}
	};

	$.validator = {
		defaults: {},
		messages: {},
		methods: {},
		setDefaults: function(opts){ $.extend(this.defaults, opts || {}); },
		addMethod: function(name, fn, message){
			this.methods[name] = fn || function(){ return true; };
			if (message) { this.messages[name] = message; }
		}
	};

	$.fn.validate = function(options){
		this.each(function(){
			$(this).data('validator', new Validator(options, this));
		});
		return this;
	};

	$.fn.valid = function(){ return true; };

})(jQuery);
